        int start = sb.indexOf("${");
        if (start < 0) {
            break;
        }
        int end = sb.indexOf("}", start + 2);
        if (end < 0) {
            break;
        }
        String varName = sb.substring(start + 2, end);
        String varValue = props.getProperty(varName);
        if (varValue == null) {
            // If variable not found, leave it as is
