            long end = Long.parseLong(parts[1]);
            if (start <= end) {
                ranges.add(SequenceRange.createStartAndEnd(start, end));
            }
        } catch (NumberFormatException e) {
            // Log or handle invalid format
        }
    }
    return ranges;
